import org.eclipse.swt.graphics.Device;
import org.eclipse.swt.graphics.Image;
import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.Display;

public class ImageCreator {
    public Image createGrayImage(Device display, Image sourceImage) {
        // This line will be matched
        return new Image(display, sourceImage, SWT.IMAGE_GRAY);
    }

    public static void main(String[] args) {
        Display display = new Display();
        try {
            // Create dummy images for demonstration
            Image source = new Image(display, 10, 10); 
            ImageCreator creator = new ImageCreator();
            Image grayImage = creator.createGrayImage(display, source);

            // Dispose images
            grayImage.dispose();
            source.dispose();
        } finally {
            display.dispose();
        }
    }
}

